-- C10 / P10.4 — versioned provider adapters and compliance profiles; provider rules stay out of core workflow logic.
create table if not exists public.command_center_social_platform_adapter_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 adapter_event_id text not null check(btrim(adapter_event_id)<>''), adapter_id text not null check(btrim(adapter_id)<>''), platform text not null check(btrim(platform)<>''), adapter_version integer not null check(adapter_version>0),
 implementation_ref text not null check(btrim(implementation_ref)<>''), source_refs text[] not null check(cardinality(source_refs)>0), observed_at timestamptz not null,
 primary key(owner_id,adapter_event_id), unique(owner_id,adapter_id,adapter_version)
);
create table if not exists public.command_center_social_platform_profile_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 profile_event_id text not null check(btrim(profile_event_id)<>''), profile_key text not null check(btrim(profile_key)<>''), platform text not null check(btrim(platform)<>''), profile_version integer not null check(profile_version>0),
 adapter_id text not null check(btrim(adapter_id)<>''), adapter_version integer not null check(adapter_version>0), max_caption_chars integer not null check(max_caption_chars>0), allowed_media_kinds text[] not null check(cardinality(allowed_media_kinds)>0),
 required_disclosure_tags text[] not null default '{}'::text[], provider_constraints jsonb not null default '{}'::jsonb check(jsonb_typeof(provider_constraints)='object'), source_refs text[] not null check(cardinality(source_refs)>0), observed_at timestamptz not null,
 primary key(owner_id,profile_event_id), unique(owner_id,profile_key,profile_version), foreign key(owner_id,adapter_id,adapter_version) references public.command_center_social_platform_adapter_history(owner_id,adapter_id,adapter_version) on delete restrict
);
create or replace view public.command_center_social_platform_profiles_current with (security_invoker=true) as select distinct on(owner_id,profile_key) owner_id,profile_event_id,profile_key,platform,profile_version,adapter_id,adapter_version,max_caption_chars,allowed_media_kinds,required_disclosure_tags,provider_constraints,source_refs,observed_at from public.command_center_social_platform_profile_history order by owner_id,profile_key,profile_version desc,observed_at desc;
create or replace function public.command_center_reject_social_platform_profile_history_mutation() returns trigger language plpgsql set search_path to 'public' as $$ begin raise exception 'Social platform profile history is immutable'; end $$;
drop trigger if exists command_center_social_platform_adapter_history_immutable on public.command_center_social_platform_adapter_history; create trigger command_center_social_platform_adapter_history_immutable before update or delete on public.command_center_social_platform_adapter_history for each row execute function public.command_center_reject_social_platform_profile_history_mutation();
drop trigger if exists command_center_social_platform_profile_history_immutable on public.command_center_social_platform_profile_history; create trigger command_center_social_platform_profile_history_immutable before update or delete on public.command_center_social_platform_profile_history for each row execute function public.command_center_reject_social_platform_profile_history_mutation();
alter table public.command_center_social_platform_adapter_history enable row level security; alter table public.command_center_social_platform_profile_history enable row level security;
revoke all on table public.command_center_social_platform_adapter_history,public.command_center_social_platform_profile_history from public,anon,authenticated; grant select,insert on table public.command_center_social_platform_adapter_history,public.command_center_social_platform_profile_history to authenticated; grant select on table public.command_center_social_platform_profiles_current to authenticated;
create policy p10_4_social_platform_adapter_owner_select on public.command_center_social_platform_adapter_history for select to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p10_4_social_platform_adapter_owner_insert on public.command_center_social_platform_adapter_history for insert to authenticated with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p10_4_social_platform_profile_owner_select on public.command_center_social_platform_profile_history for select to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p10_4_social_platform_profile_owner_insert on public.command_center_social_platform_profile_history for insert to authenticated with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
